def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # id -> (side, price, arrival_time, remaining_qty)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, arr_time, remaining_qty = order_map[cancel_id]
                if remaining_qty > 0:
                    if side == 'buy':
                        buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != cancel_id]
                    else:
                        sell_book = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != cancel_id]
                    order_map[cancel_id] = (side, price, arr_time, 0)
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = None if order_type == 'market' else order[3]

            remaining_qty = qty

            if side == 'buy':
                # Match against sell book
                new_sell_book = []
                for sell_price, sell_arr_time, sell_id, sell_qty in sell_book:
                    if remaining_qty == 0:
                        new_sell_book.append((sell_price, sell_arr_time, sell_id, sell_qty))
                    elif price is None or sell_price <= price:
                        # Match occurs
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_qty -= trade_qty
                        if sell_qty > 0:
                            new_sell_book.append((sell_price, sell_arr_time, sell_id, sell_qty))
                        order_map[sell_id] = (order_map[sell_id][0], order_map[sell_id][1], order_map[sell_id][2], sell_qty)
                    else:
                        new_sell_book.append((sell_price, sell_arr_time, sell_id, sell_qty))
                sell_book = new_sell_book
            else:
                # Match against buy book
                new_buy_book = []
                for buy_price, buy_arr_time, buy_id, buy_qty in buy_book:
                    if remaining_qty == 0:
                        new_buy_book.append((buy_price, buy_arr_time, buy_id, buy_qty))
                    elif price is None or buy_price >= price:
                        # Match occurs
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining_qty -= trade_qty
                        buy_qty -= trade_qty
                        if buy_qty > 0:
                            new_buy_book.append((buy_price, buy_arr_time, buy_id, buy_qty))
                        order_map[buy_id] = (order_map[buy_id][0], order_map[buy_id][1], order_map[buy_id][2], buy_qty)
                    else:
                        new_buy_book.append((buy_price, buy_arr_time, buy_id, buy_qty))
                buy_book = new_buy_book

            # Add to order map
            order_map[order_id] = (side, price, arrival_time, remaining_qty)

            # If limit order and there's remaining qty, add to book
            if (order_type == 'limit' or order_type == 'ioc') and remaining_qty > 0:
                if order_type == 'limit':
                    if side == 'buy':
                        buy_book.append((price, arrival_time, order_id, remaining_qty))
                        buy_book.sort(key=lambda x: (-x[0], x[1]))
                    else:
                        sell_book.append((price, arrival_time, order_id, remaining_qty))
                        sell_book.sort(key=lambda x: (x[0], x[1]))

            arrival_time += 1

    return trades

